local KEY = [[Item-w:v20:20260821]]
local function decode(blob, key)
	local raw = HttpService:Base64Decode((blob:gsub("%s+", "")))
	local out = table.create(#raw)
	for i = 1, #raw do
		local b = string.byte(raw, i)
		local k = string.byte(key, ((i - 1) % #key) + 1)
		out[i] = string.char(bit32.bxor(b, k))
	end
	return table.concat(out)
end
local source = decode(PAYLOAD, KEY)
local chunk, err = loadstring(source)
if not chunk then
	error(err)
end
return chunk()